SELECT b.id AS bookId, b.title AS bookTitle, b.author AS author, b.cover_url AS bookCover, b.category_id AS categoryId, c.name AS categoryName, b.average_score AS averageScore, b.score_count AS scoreCount, b.favorite_count AS favoriteCount, b.hot_score AS hotScore, b.create_time AS createTime FROM book b LEFT JOIN category c ON b.category_id = c.id WHERE b.category_id IN
#{id}
ORDER BY COALESCE(b.hot_score, 0) DESC, COALESCE(b.favorite_count, 0) DESC, COALESCE(b.average_score, 0) DESC, b.create_time DESC LIMIT #{limit}

SELECT b.id AS bookId, b.title AS bookTitle, b.author AS author, b.cover_url AS bookCover, b.category_id AS categoryId, c.name AS categoryName, b.average_score AS averageScore, b.score_count AS scoreCount, b.favorite_count AS favoriteCount, b.hot_score AS hotScore, b.create_time AS createTime FROM book b LEFT JOIN category c ON b.category_id = c.id WHERE b.author IN
#{author}
ORDER BY COALESCE(b.hot_score, 0) DESC, COALESCE(b.favorite_count, 0) DESC, COALESCE(b.average_score, 0) DESC, b.create_time DESC LIMIT #{limit}
